  ('fr_aib_residual_mix_2024', 'Association of Issuing Bodies — European Residual Mixes 2024', 'The residual mix of each European country for 2024, what is left of its electricity once guarantees of origin are cancelled, with its direct CO2 per kWh, as the Association of Issuing Bodies calculates it for electricity disclosure.', 'text', 'https://www.aib-net.org/sites/default/files/assets/eecs/Residual%20Mix/2024_Final%20_Residual%20mix%20calculation%20results_11082025.pdf', 'https://www.aib-net.org/facts/european-residual-mix/2024', 'none', array['FR']::text[], '{}'::text[], 'Terms not stated', null, null, false, 'pack:fr'),
