  ('parcelle', 'Cadastral parcel', 'The 14-character identifier of a cadastral parcel: municipality (5), prefix (3), section (2), number (4).', '^[0-9][0-9AB][0-9]{3}[0-9A-Z]{3}[0-9A-Z]{2}[0-9]{4}$', 'https://cadastre.data.gouv.fr/map?parcelleId={value}', 'cadastre', null, 'pack:fr'),
