  ('rnb_id', 'RNB building', 'The 12-character identifier of a building in the Référentiel National des Bâtiments.', '^[A-Z0-9]{12}$', 'https://rnb.beta.gouv.fr/batiments/{value}', 'rnb', null, 'pack:fr'),
  ('siren', 'SIREN', 'The 9-digit identifier of a company in the national register.', '^[0-9]{9}$', 'https://annuaire-entreprises.data.gouv.fr/entreprise/{value}', 'sirene', '0002', 'pack:fr'),
